import nbformat
from nbconvert.preprocessors import ExecutePreprocessor
nb=nbformat.read('FS-Filters.ipynb', as_version=4)
ep=ExecutePreprocessor(timeout=-1, kernel_name='python3', allow_errors=True)
ep.preprocess(nb, {'metadata': {'path': '/code'}})
for idx in [8,10,19,22]:
    cell=nb.cells[idx]
    print('\nCELL', idx)
    for out in cell.get('outputs',[]):
        if out.output_type=='stream':
            print(out.text)
        elif out.output_type=='execute_result':
            print(out['data'].get('text/plain',''))
        elif out.output_type=='display_data':
            print(out['data'].get('text/plain','[display]'))
        elif out.output_type=='error':
            print('ERROR', out.ename, out.evalue)
